head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25113";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil25113.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_57", fn: function(){ return (!((1===1) || (1===2) || (1===3) || (1===4))); } }, { id: "c_otherwise_81", fn: function(){ return (!((1>=4))); } }, { id: "c_otherwise_57_r1", fn: function(){ return (!((2===1) || (2===2) || (2===3) || (2===4))); } }, { id: "c_otherwise_81_r1", fn: function(){ return (!((2>=4))); } }, { id: "c_otherwise_57_r2", fn: function(){ return (!((3===1) || (3===2) || (3===3) || (3===4))); } }, { id: "c_otherwise_81_r2", fn: function(){ return (!((3>=4))); } }, { id: "c_otherwise_57_r3", fn: function(){ return (!((4===1) || (4===2) || (4===3) || (4===4))); } }, { id: "c_otherwise_81_r3", fn: function(){ return (!((4>=4))); } }, { id: "c_otherwise_57_r4", fn: function(){ return (!((5===1) || (5===2) || (5===3) || (5===4))); } }, { id: "c_otherwise_81_r4", fn: function(){ return (!((5>=4))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();
        scwin.chkChrgDesignReadonly();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25113.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_GoDsclInsert_onclick
 * @description 「신고서 제출하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoDsclInsert_onclick = async function(e){
    try {
        await scwin.goDsclInsert()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil25113.btn_GoDsclInsert_onclick" });
    }
};

