///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoDsclInsert
 * @description Go Dscl Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoDsclInsert = async function () {
    const sbmOptions = {
        id: "tx_fn_GoDsclInsert",
        method: "post",
        action: "/submission/searchDisclosureForm.do",
        ref: "dma_GoDsclInsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goDsclInsert
 * @description go Dscl Insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goDsclInsert = async function () {
    await scwin.tx_fn_GoDsclInsert();
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _doFlag _doFlag
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_doFlag, _tpCd) {
    const frm = $c.util.getComponent('dgCorpDisclsChrgForm' + _tpCd);
    if (_doFlag === 'insert') {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "직위"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "유선전화번호"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_telNo'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_chrgInnrNo'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_chrgInnrNo')))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "내선"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgInnrNo'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "휴대전화번호"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_cellphoneNo'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "FAX"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_faxNo'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    $c.util.getComponent('dma_GoDsclInsertReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    $c.util.getComponent('dma_GoDsclInsertReq').set('chrgDesignDd', $c.util.getComponent('ipt_chrgDesignYear').getValue()+ $c.util.getComponent('ipt_chrgDesignMonth').getValue()+ $c.util.getComponent('ipt_chrgDesignDay').getValue());
    if (!$c.str.isEmail($c.util.getComponent('dma_GoDsclInsertReq').get('email'))) {
        return;
    }
    $c.util.getComponent('dma_GoDsclInsertReq').set('doFlag', _doFlag);
    $c.util.getComponent('dma_GoDsclInsertReq').set('method', 'modifyDigitalCorpDisclsChrg');
    frm.action = 'corpDiscls.do';
    await scwin.tx_fn_Modify();
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @returns {void}
 * @hidden N
 */
scwin.goURL = function () {
    document.location.href = "/";
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    for (let i = 1; i <= 5; i++) {
        const frm = $c.util.getComponent('dgCorpDisclsChrgForm' + i);
        ((v) => { let cur = String(v ?? ""); for (let i = 2; i >= 1; i--) { const idx = cur.lastIndexOf("@"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("email" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_GoDsclInsertReq').get('email'));
        const chrgDesignDdVal = $c.util.getComponent('dma_GoDsclInsertReq').get('chrgDesignDd');
        $c.util.getComponent("ipt_chrgDesignYear").setValue(chrgDesignDdVal.substring(0, 4));
        $c.util.getComponent("ipt_chrgDesignMonth").setValue(chrgDesignDdVal.substring(4, 6));
        $c.util.getComponent("ipt_chrgDesignDay").setValue(chrgDesignDdVal.substring(6));
    }
};

/**
 * @method
 * @name chkChrgDesignReadonly
 * @description chk Chrg Design Readonly 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkChrgDesignReadonly = function () {
    let frm;
    for (let i = 1; i <= 5; i++) {
        frm = $c.util.getComponent('dgCorpDisclsChrgForm' + i);
        if (($c.util.getComponent('ipt_chrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) !== '') {
            $c.util.getComponent('ipt_chrgNm').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignYear').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignMonth').readOnly = true;
            $c.util.getComponent('ipt_chrgDesignDay').readOnly = true;
        } else {
            $c.util.getComponent('ipt_chrgNm').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignYear').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignMonth').readOnly = false;
            $c.util.getComponent('ipt_chrgDesignDay').readOnly = false;
            ($c.util.getComponent('updateBtn' + i) && $c.util.getComponent('updateBtn' + i).hide ? $c.util.getComponent('updateBtn' + i).hide() : console.warn('[sdd] hide 대상 미해결: ' + 'updateBtn' + i));
        }
    }
};
